output_text:
[
  {
    "id": "must_check_out_cart",
    "text": "A shopper must check out the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "cart_required_for_items",
    "text": "Items should only be picked up while the shopper is using a cart.",
    "abstraction": {
      "state_properties": {
        "not_using_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          "not_using_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers must not carry merchandise loose in their hands.",
    "abstraction": {
      "state_properties": {
        "hand_carrying": "handFull"
      },
      "events": {
        "pickup_into_hand": {
          "pre": "PICKUP_ITEM",
          "post": "hand_carrying"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "hand_carrying",
          "pickup_into_hand"
        ]
      }
    }
  },
  {
    "id": "return_cart_before_leaving",
    "text": "After taking a cart, the shopper must return it to the cart-return point before the trip ends.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "returned_cart_waiting": {
          "and": [
            "at(0,1)",
            "cartAt(0,1)"
          ]
        }
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "cart_returned": {
          "pre": {
            "and": [
              "cart_return_point",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "returned_cart_waiting"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned"
    }
  },
  {
    "id": "leave_cart_only_at_return_point",
    "text": "A cart may be put down only at the designated return point.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return": "at(0,1)"
      },
      "events": {
        "cart_drop": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_drop",
          {
            "not": "designated_cart_return"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers must not exit the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_attempt": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_attempt",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "no_interaction_after_cart_return",
    "text": "Once the cart has been returned, the shopper should not resume shopping or perform any further store interaction.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "cart_free_exit_zone",
    "text": "Carts are not allowed in the right-hand exit zone of the store.",
    "abstraction": {
      "state_properties": {
        "right_exit_zone": {
          "or": [
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "right_exit_zone",
          "pushing_cart"
        ]
      }
    }
  }
]
